const researchHistoryKey="helix-seo-research-history.v1";function readResearchHistory(){try{const rows=JSON.parse(localStorage.getItem(researchHistoryKey)??"[]");return Array.isArray(rows)?rows.slice(0,50):[]}catch{return[]}}function renderResearchHistory(){const rows=readResearchHistory();document.querySelector("#research-history").innerHTML=rows.length?rows.map((row)=>`<button class="site-list-item history-item" type="button" data-kind="${escapeHtml(row.kind)}" data-value="${escapeHtml(row.value)}"><span><strong>${escapeHtml(row.value)}</strong><small>${escapeHtml(row.kind)} · ${escapeHtml(row.site_id)} · ${new Date(row.recorded_at).toLocaleString("ja-JP")}</small></span><em>再実行</em></button>`).join(""):'<div class="empty"><strong>履歴なし</strong><span>検索語はこのブラウザ内だけに保存されます。</span></div>';document.querySelectorAll(".history-item").forEach((button)=>button.addEventListener("click",()=>{const controls={quick:quickSearchInput,suggest:suggestInput,demand:demandSearchInput,question:aiQuestionSearch},control=controls[button.dataset.kind];if(!control)return;control.value=button.dataset.value;if(button.dataset.kind==="quick"){renderQuickSearch();activateView("quick-search")}else if(button.dataset.kind==="suggest"){syncResearchUrl("suggest");renderSuggestExplorer();activateView("suggest-explorer")}else if(button.dataset.kind==="demand"){syncDemandUrl();renderDemandSearch();activateView("demand-search")}else{syncResearchUrl("question");renderAiQuestions();activateView("ai-questions")}}))}function rememberResearch(kind,value){const normalized=String(value??"").normalize("NFKC").trim();if(!normalized)return;const row={kind,value:normalized,site_id:siteSelector.value,recorded_at:new Date().toISOString()},rows=readResearchHistory().filter((item)=>!(item.kind===kind&&item.site_id===row.site_id&&item.value===row.value));try{localStorage.setItem(researchHistoryKey,JSON.stringify([row,...rows].slice(0,50)))}catch{}renderResearchHistory()}
function renderSuggestExplorer(){const seed=suggestInput.value.normalize("NFKC").trim().toLocaleLowerCase("ja-JP"),tokens=seed.split(/\s+/u).filter(Boolean),site=data.sites.find((row)=>row.site_id===siteSelector.value),summary=site?.suggest_evidence_oracle?.summary??{},inventory=data.keyword_inventory.filter((row)=>row.site_id===siteSelector.value),matches=seed?inventory.filter((row)=>{const value=row.normalized_keyword.toLocaleLowerCase("ja-JP");return suggestMode.value==="prefix"?value.startsWith(seed):suggestMode.value==="contains"?value.includes(seed):tokens.every((token)=>value.includes(token))}).sort((a,b)=>(Number(b.search_volume??-1)-Number(a.search_volume??-1))||a.source_order_index-b.source_order_index):[];document.querySelector("#suggest-metrics").innerHTML=[["一致元行",matches.length],["正規化候補",summary.normalized_candidate_count??0],["重複候補",summary.normalized_duplicate_candidate_count??0],["volume競合",summary.volume_conflict_count??0],["SERP取得済",matches.filter((row)=>row.processing_state!=="SERP未取得").length],["外部surface",0]].map(([label,value])=>`<div class="metric"><span>${label}</span><strong>${yen.format(value)}</strong><small>件</small></div>`).join("");suggestRows.innerHTML=matches.slice(0,500).map((row)=>{const value=row.normalized_keyword.toLocaleLowerCase("ja-JP"),matchKind=value===seed?"完全一致":value.startsWith(seed)?"前方一致":"包含";return`<tr><td><strong>${escapeHtml(row.raw_keyword)}</strong></td><td>${matchKind}</td><td>${formatVolume(row.search_volume)}</td><td>${escapeHtml(row.processing_state)}</td><td>${escapeHtml(row.source_sheet)}</td><td>${escapeHtml(row.source_location)}</td></tr>`}).join("");suggestEmpty.hidden=Boolean(seed&&matches.length);suggestEmpty.innerHTML=!seed?"<strong>seedを入力</strong><span>外部surfaceへの通信・課金は行いません。</span>":matches.length?"":`<strong>一致なし</strong><span>保有workbookに候補がありません。外部suggest未取得とは区別されます。</span>`}
