  const start=(currentPage-1)*pageSize;
  const visibleRows=rows.slice(start,start+pageSize);
  rowsRoot.innerHTML=visibleRows.map((row)=>{const aioPresent=row.group.strategy.aio_observed_queries>0;const path=row.group.category_path??[row.group.category];const categories=Array.from({length:categoryDepth},(_,index)=>path[index]??"—");return `<tr data-id="${escapeHtml(row.group.id)}">${categories.map((category)=>`<td>${escapeHtml(category)}</td>`).join("")}<td><strong>${escapeHtml(row.keyword)}</strong></td><td class="search-volume"><strong>${row.group.search_volume==null?"未取得":yen.format(row.group.search_volume)}</strong></td><td>${row.group.intent_keywords.length}語</td><td><span class="aio-state ${aioPresent?"present":"absent"}">${aioPresent?"あり":"なし"}</span></td><td><strong>${escapeHtml(pageTypeLabels[row.group.strategy.recommended_page_type]??row.group.strategy.recommended_page_type)}</strong></td><td>${escapeHtml(row.group.state)}</td><td><span class="match-state ${escapeHtml(row.group.article_match?.state??"unmatched")}">${escapeHtml(articleMatchLabel(row.group))}</span></td><td><button class="detail-button" type="button">詳細</button></td></tr>`}).join("");
  rowsRoot.querySelectorAll("tr").forEach((tr)=>{const group=data.groups.find((item)=>item.id===tr.dataset.id);tr.querySelector(".search-volume strong").textContent=formatVolume(group.search_volume)});
