function executeUtility(){const summary=document.querySelector("#utility-summary");try{if(utilityMode.value==="replace"&&!utilitySearch.value)throw new Error("置換前の文字列を入力してください");let rows;if(utilityMode.value==="local"){const keywords=[...new Set(utilityLeft.value.split(/\r?\n/u).map((value)=>value.trim()).filter(Boolean))];if(!keywords.length)throw new Error("リストAへ元キーワードを入力してください");let selected;if(localityScope.value==="prefecture")selected=locationData.prefectures.filter((row)=>localityPrefecture.value==="all"||row.name===localityPrefecture.value).map((row)=>row.name);else if(localityScope.value==="municipality")selected=locationData.municipalities.filter((row)=>localityPrefecture.value==="all"||row.prefecture===localityPrefecture.value).map((row)=>row.municipality);else selected=locationData.stations.map((row)=>`${row.name}駅`);if(keywords.length*selected.length>20000)throw new Error("生成上限20,000行です。キーワードまたは地域粒度を絞り込んでください");rows=keywords.flatMap((keyword)=>selected.map((place)=>`${keyword} ${place}`));const provenance=localityScope.value==="station"?`国交省 ${locationData.station_source.dataset_year}年度版`:`日本郵便 ${locationData.source.updated_at}版`;summary.innerHTML=`<strong>${yen.format(rows.length)}行</strong><span>${escapeHtml(provenance)} · ${yen.format(selected.length)}地域 · digest ${escapeHtml(locationData.evidence_digest.slice(0,12))}</span>`}else{rows=runKeywordUtility(utilityMode.value,utilityLeft.value,utilityRight.value,{search:utilitySearch.value,replacement:utilityReplacement.value});summary.innerHTML=`<strong>${yen.format(rows.length)}行</strong><span>ブラウザ内処理・通信なし・DB保存なし</span>`}utilityResult.value=rows.join("\n")}catch(error){summary.innerHTML=`<strong>実行できません</strong><span>${escapeHtml(error.message)}</span>`}}
