function restoreUniversalFilterState(){for(const control of universalFilterControls()){const value=requestParams.get(filterStateKey(control.id));if(value==null)continue;if(control instanceof HTMLSelectElement&&![...control.options].some((option)=>option.value===value))continue;control.value=value;control.dispatchEvent(new Event(control.type==="search"||control.tagName==="INPUT"?"input":"change",{bubbles:true}))}}
function syncUniversalFilterState(control){const url=new URL(location.href),key=filterStateKey(control.id),defaultValue=control instanceof HTMLSelectElement?control.options[0]?.value??"":control.defaultValue??"";control.value&&control.value!==defaultValue?url.searchParams.set(key,control.value):url.searchParams.delete(key);history.replaceState(null,"",url)}
