function collectEditorialReviewDecisions(){const packet=data.sites.find((row)=>row.site_id===siteSelector.value)?.content_editorial_review_packet,root=document.querySelector("#editorial-review-rows"),decisions=[];for(const item of packet?.items??[]){const preference=root.querySelector(`.editorial-preference-input[data-review-id="${CSS.escape(item.review_id)}"]`);if(!preference?.value)continue;const scores={a:{},b:{}},missing=[];for(const side of ["a","b"])for(const criterion of editorialCriteria){const control=root.querySelector(`.editorial-score[data-review-id="${CSS.escape(item.review_id)}"][data-side="${side}"][data-criterion="${criterion}"]`),score=Number(control?.value);control?.classList.toggle("editorial-invalid",!Number.isInteger(score)||score<1||score>5);if(!Number.isInteger(score)||score<1||score>5)missing.push(`${side}.${criterion}`);else scores[side][criterion]=score}let semantic_preservation=null;if(item.semantic_preservation_required){semantic_preservation={};for(const side of ["a","b"]){const control=root.querySelector(`.editorial-semantic-input[data-review-id="${CSS.escape(item.review_id)}"][data-side="${side}"]`);control?.classList.toggle("editorial-invalid",!control?.value);if(!control?.value)missing.push(`semantic.${side}`);else semantic_preservation[side]=control.value==="true"}}if(missing.length)throw new Error(`${item.main_keyword}: ${missing.join(", ")} が未入力`);decisions.push({review_id:item.review_id,preference:preference.value,scores,semantic_preservation,reviewed_at:new Date().toISOString(),notes:""})}return{packet,decisions}}
