document.querySelector("#editorial-review-export").addEventListener("click",exportEditorialReviewDecisions);document.querySelector("#editorial-review-rows").addEventListener("change",()=>{const count=[...document.querySelectorAll("#editorial-review-rows .editorial-preference-input")].filter((control)=>control.value).length;document.querySelector("#editorial-review-export-status").textContent=`入力${count}件`});
function tableStateKey(table){if(table.dataset.sortKey)return table.dataset.sortKey;const scope=table.closest(".view,dialog")??document.body,scopeId=scope.id||"document",index=[...scope.querySelectorAll("table")].indexOf(table);return table.dataset.sortKey=`${scopeId}.${Math.max(index,0)}`}
function tableSnapshot(tbody){return[...tbody.rows].map((row)=>row.textContent).join("\u0000")}
function applyTableSort(table,column,direction,{persist=true}={}){const tbody=table.tBodies[0];if(!tbody||column<0||column>=(table.tHead?.rows[0]?.cells.length??0))return;const rows=[...tbody.rows].map((row,index)=>({row,index}));rows.sort((left,right)=>compareCellText(left.row.cells[column]?.textContent,right.row.cells[column]?.textContent,direction)||left.index-right.index);rows.forEach(({row})=>tbody.append(row));for(const header of table.tHead.rows[0].cells)header.removeAttribute("aria-sort");table.tHead.rows[0].cells[column].setAttribute("aria-sort",direction==="asc"?"ascending":"descending");tbody.dataset.sortSnapshot=tableSnapshot(tbody);if(persist){const url=new URL(location.href);url.searchParams.set(sortStateKey(tableStateKey(table)),`${column}:${direction}`);history.replaceState(null,"",url)}}
function initializeSortableTable(table){if(table.dataset.sortInitialized||!table.tHead?.rows[0]||!table.tBodies[0])return;table.dataset.sortInitialized="true";const key=tableStateKey(table);[...table.tHead.rows[0].cells].forEach((header)=>{header.tabIndex=0;header.dataset.sortColumn=String(header.cellIndex);header.title="クリックで並べ替え"});const saved=parseSortState(new URL(location.href).searchParams.get(sortStateKey(key)));if(saved)applyTableSort(table,saved.column,saved.direction,{persist:false})}
document.addEventListener("click",(event)=>{const header=event.target.closest("th[data-sort-column]");if(!header)return;const table=header.closest("table"),current=header.getAttribute("aria-sort"),direction=current==="ascending"?"desc":"asc";applyTableSort(table,Number(header.dataset.sortColumn),direction)});document.addEventListener("keydown",(event)=>{if(!["Enter"," "].includes(event.key)||!event.target.matches("th[data-sort-column]"))return;event.preventDefault();event.target.click()});
const tableObserver=new MutationObserver(()=>{for(const table of document.querySelectorAll("table")){initializeSortableTable(table);const tbody=table.tBodies[0],saved=parseSortState(new URL(location.href).searchParams.get(sortStateKey(tableStateKey(table))));if(saved&&tbody&&tbody.dataset.sortSnapshot!==tableSnapshot(tbody))applyTableSort(table,saved.column,saved.direction,{persist:false})}});tableObserver.observe(document.body,{childList:true,subtree:true});document.querySelectorAll("table").forEach(initializeSortableTable);
